-- BAY-66: replace broad year-long windows with explicit sequential phases.
-- Values are stored as Africa/Douala instants and remain editable through the
-- reporting-period configuration UI.

UPDATE academic_reporting_period p
   SET timezone='Africa/Douala',
       grade_entry_opens_at=v.grade_open, grade_entry_closes_at=v.grade_close,
       teacher_submission_opens_at=v.submit_open, teacher_submission_closes_at=v.submit_close,
       review_opens_at=v.review_open, review_closes_at=v.review_close,
       validation_opens_at=v.validate_open, validation_closes_at=v.validate_close,
       bulletin_publish_opens_at=v.publish_open, bulletin_publish_closes_at=v.publish_close,
       correction_opens_at=v.correct_open, correction_closes_at=v.correct_close
  FROM (VALUES
    ('S1','2026-09-01 07:00:00+01'::timestamptz,'2026-10-02 18:00:00+01'::timestamptz,'2026-10-05 07:00:00+01'::timestamptz,'2026-10-09 18:00:00+01'::timestamptz,'2026-10-10 07:00:00+01'::timestamptz,'2026-10-16 18:00:00+01'::timestamptz,'2026-10-17 07:00:00+01'::timestamptz,'2026-10-23 18:00:00+01'::timestamptz,'2026-10-24 07:00:00+01'::timestamptz,'2026-10-30 18:00:00+01'::timestamptz,'2026-10-31 07:00:00+01'::timestamptz,'2026-11-06 18:00:00+01'::timestamptz),
